-- ----------------------------------------------------------------
-- `item_template` is split in two: `item_sparse` keeps the client fields
-- of the items the 15595 client's files do not hold, and `item_template`
-- keeps the fields no client file holds, for every item.
--
-- The server takes every field the client reads of an item from the
-- client's Item.db2 and Item-sparse.db2, so for the 54,086 items those
-- files hold, the copies in `item_template` are never read. They go.
-- `item_sparse` takes the client fields of every other item (8,000 in this
-- repository, and any an operator added) and of any item `hotfix_data`
-- lists for Item-sparse, whose values the server keeps. `item_template`
-- keeps the entry, the proc rates, durability, the disenchant skill and
-- loot, the food type, the money loot and the extra flags. `Unknown2` goes:
-- nothing reads it.
--
-- The client's columns keep their names and take the client's types.
-- The split runs only while `item_template` still has its `name` column,
-- so a run that failed part-way is recovered by running the file again.
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '10';
    SET @cOldContent = '006';

    SET @cNewVersion = '22';
    SET @cNewStructure = '11';
    SET @cNewContent = '001';
    SET @cNewDescription = 'Split_Item_Template';
    SET @cNewComment = 'item_sparse holds the client fields of the items the 15595 client files do not hold';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
        IF EXISTS (SELECT 1 FROM `information_schema`.`COLUMNS`
                    WHERE `TABLE_SCHEMA` = DATABASE() AND `TABLE_NAME` = 'item_template'
                      AND `COLUMN_NAME` = 'name') THEN
            DROP TABLE IF EXISTS `item_sparse`;
            CREATE TABLE `item_sparse` (
                `entry` mediumint(8) unsigned NOT NULL DEFAULT 0 COMMENT 'Item prototype ID (See item_template.entry).',
                `class` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Class of the item.',
                `subclass` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'The subclass of the item template.',
                `unk0` int(11) NOT NULL DEFAULT -1,
                `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Item name.',
                `displayid` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'A display model identifier for the Item.',
                `Quality` int(11) NOT NULL DEFAULT 0 COMMENT 'Quality of item.',
                `Flags` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Item prototype flags.',
                `Flags2` int(10) unsigned NOT NULL DEFAULT 0,
                `Unknown` float NOT NULL DEFAULT 0,
                `Unknown1` float NOT NULL DEFAULT 0,
                `BuyCount` int(11) NOT NULL DEFAULT 1 COMMENT 'Stack size by vendors.',
                `BuyPrice` int(11) NOT NULL DEFAULT 0 COMMENT 'Item buying price (coppers).',
                `SellPrice` int(11) NOT NULL DEFAULT 0 COMMENT 'Item selling price (coppers).',
                `InventoryType` int(11) NOT NULL DEFAULT 0 COMMENT 'Inventory type.',
                `AllowableClass` int(11) NOT NULL DEFAULT -1 COMMENT 'Mask of allowed classes.',
                `AllowableRace` int(11) NOT NULL DEFAULT -1 COMMENT 'Mask of allowed races.',
                `ItemLevel` int(11) NOT NULL DEFAULT 0 COMMENT 'Level of item.',
                `RequiredLevel` int(11) NOT NULL DEFAULT 0 COMMENT 'Required level.',
                `RequiredSkill` int(11) NOT NULL DEFAULT 0 COMMENT 'Required skill type.',
                `RequiredSkillRank` int(11) NOT NULL DEFAULT 0 COMMENT 'Required skill value.',
                `requiredspell` int(11) NOT NULL DEFAULT 0 COMMENT 'Required spell (See Spell.dbc).',
                `requiredhonorrank` int(11) NOT NULL DEFAULT 0 COMMENT 'Required honor rank.',
                `RequiredCityRank` int(11) NOT NULL DEFAULT 0 COMMENT 'DEPRECATED: the city rank required. City ranks did not make it into WoW.',
                `RequiredReputationFaction` int(11) NOT NULL DEFAULT 0 COMMENT 'Required faction for reputation check (See Faction.dbc).',
                `RequiredReputationRank` int(11) NOT NULL DEFAULT 0 COMMENT 'Required minimal reputation rank.',
                `maxcount` int(11) NOT NULL DEFAULT -1 COMMENT 'The maximum amount of copies of the item that a character may have.',
                `stackable` int(11) NOT NULL DEFAULT 1 COMMENT 'Maximum stack size.',
                `ContainerSlots` int(11) NOT NULL DEFAULT 0 COMMENT 'Defines the amount of slots for items of type container or ammunition container.',
                `stat_type1` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value1` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_1` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_1` int(11) NOT NULL DEFAULT 0,
                `stat_type2` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value2` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_2` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_2` int(11) NOT NULL DEFAULT 0,
                `stat_type3` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value3` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_3` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_3` int(11) NOT NULL DEFAULT 0,
                `stat_type4` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value4` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_4` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_4` int(11) NOT NULL DEFAULT 0,
                `stat_type5` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value5` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_5` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_5` int(11) NOT NULL DEFAULT 0,
                `stat_type6` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value6` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_6` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_6` int(11) NOT NULL DEFAULT 0,
                `stat_type7` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value7` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_7` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_7` int(11) NOT NULL DEFAULT 0,
                `stat_type8` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value8` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_8` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_8` int(11) NOT NULL DEFAULT 0,
                `stat_type9` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value9` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_9` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_9` int(11) NOT NULL DEFAULT 0,
                `stat_type10` int(11) NOT NULL DEFAULT 0 COMMENT 'An item modifier to apply for this item.',
                `stat_value10` int(11) NOT NULL DEFAULT 0 COMMENT 'The value to add for the matching modifier.',
                `stat_unk1_10` int(11) NOT NULL DEFAULT 0,
                `stat_unk2_10` int(11) NOT NULL DEFAULT 0,
                `ScalingStatDistribution` int(11) NOT NULL DEFAULT 0,
                `DamageType` int(11) NOT NULL DEFAULT 0,
                `delay` int(11) NOT NULL DEFAULT 0 COMMENT 'The delay in milliseconds between successive hits for the item.',
                `RangedModRange` float NOT NULL DEFAULT 0,
                `spellid_1` int(11) NOT NULL DEFAULT 0 COMMENT 'If the item can cast or trigger a spell, this is the reference.',
                `spelltrigger_1` int(11) NOT NULL DEFAULT 0 COMMENT 'The type of trigger for the matching spellid entry.',
                `spellcharges_1` int(11) NOT NULL DEFAULT 0 COMMENT 'The amount of charges for the spell referenced in the matching spellid entry.',
                `spellcooldown_1` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell.',
                `spellcategory_1` int(11) NOT NULL DEFAULT 0 COMMENT 'A spell category identifier.',
                `spellcategorycooldown_1` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell category.',
                `spellid_2` int(11) NOT NULL DEFAULT 0 COMMENT 'If the item can cast or trigger a spell, this is the references.',
                `spelltrigger_2` int(11) NOT NULL DEFAULT 0 COMMENT 'The type of trigger for the matching spellid entry.',
                `spellcharges_2` int(11) NOT NULL DEFAULT 0 COMMENT 'The amount of charges for the spell referenced in the matching spellid entry.',
                `spellcooldown_2` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell.',
                `spellcategory_2` int(11) NOT NULL DEFAULT 0 COMMENT 'A spell category identifier.',
                `spellcategorycooldown_2` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell category.',
                `spellid_3` int(11) NOT NULL DEFAULT 0 COMMENT 'If the item can cast or trigger a spell, this is the references.',
                `spelltrigger_3` int(11) NOT NULL DEFAULT 0 COMMENT 'The type of trigger for the matching spellid entry.',
                `spellcharges_3` int(11) NOT NULL DEFAULT 0 COMMENT 'The amount of charges for the spell referenced in the matching spellid entry.',
                `spellcooldown_3` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell.',
                `spellcategory_3` int(11) NOT NULL DEFAULT 0 COMMENT 'A spell category identifier.',
                `spellcategorycooldown_3` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell category.',
                `spellid_4` int(11) NOT NULL DEFAULT 0 COMMENT 'If the item can cast or trigger a spell, this is the references.',
                `spelltrigger_4` int(11) NOT NULL DEFAULT 0 COMMENT 'The type of trigger for the matching spellid entry.',
                `spellcharges_4` int(11) NOT NULL DEFAULT 0 COMMENT 'The amount of charges for the spell referenced in the matching spellid entry.',
                `spellcooldown_4` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell.',
                `spellcategory_4` int(11) NOT NULL DEFAULT 0 COMMENT 'A spell category identifier.',
                `spellcategorycooldown_4` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell category.',
                `spellid_5` int(11) NOT NULL DEFAULT 0 COMMENT 'If the item can cast or trigger a spell, this is the references.',
                `spelltrigger_5` int(11) NOT NULL DEFAULT 0 COMMENT 'The type of trigger for the matching spellid entry.',
                `spellcharges_5` int(11) NOT NULL DEFAULT 0 COMMENT 'The amount of charges for the spell referenced in the matching spellid entry.',
                `spellcooldown_5` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell.',
                `spellcategory_5` int(11) NOT NULL DEFAULT 0 COMMENT 'A spell category identifier.',
                `spellcategorycooldown_5` int(11) NOT NULL DEFAULT -1 COMMENT 'The cooldown in milliseconds for the matching spell category.',
                `bonding` int(11) NOT NULL DEFAULT 0 COMMENT 'Defines if and how and item will be bound to a character.',
                `description` varchar(255) NOT NULL DEFAULT '' COMMENT 'A short - usually one sentence - description of the item. Mostly flavor texts.',
                `PageText` int(11) NOT NULL DEFAULT 0 COMMENT 'If the item should be readable, e.g. for letters.',
                `LanguageID` int(11) NOT NULL DEFAULT 0 COMMENT 'The language a readable item is written in (See Languages.dbc).',
                `PageMaterial` int(11) NOT NULL DEFAULT 0 COMMENT 'The material to be used as background for items with page texts set.',
                `startquest` int(11) NOT NULL DEFAULT 0 COMMENT 'Quest ID (See quest_template.entry).',
                `lockid` int(11) NOT NULL DEFAULT 0 COMMENT 'Lock ID (See Lock.dbc).',
                `Material` int(11) NOT NULL DEFAULT 0 COMMENT 'Material type.',
                `sheath` int(11) NOT NULL DEFAULT 0 COMMENT 'How the item is sheathed when worn.',
                `RandomProperty` int(11) NOT NULL DEFAULT 0 COMMENT 'Random property type (See item_enchantment_template.entry).',
                `RandomSuffix` int(11) NOT NULL DEFAULT 0,
                `itemset` int(11) NOT NULL DEFAULT 0 COMMENT 'If an item is part of an item set, this references the item set''s identifier.',
                `area` int(11) NOT NULL DEFAULT 0 COMMENT 'If an item is only usable in a specific zone, this is the reference (See AreaTable.dbc).',
                `Map` int(11) NOT NULL DEFAULT 0 COMMENT 'If an item is only usable on a specific map, this is the reference (See Map.dbc).',
                `BagFamily` int(11) NOT NULL DEFAULT 0 COMMENT 'If an item is a bag, a bit-mask of the item families it may hold.',
                `TotemCategory` int(11) NOT NULL DEFAULT 0,
                `socketColor_1` int(11) NOT NULL DEFAULT 0,
                `socketContent_1` int(11) NOT NULL DEFAULT 0,
                `socketColor_2` int(11) NOT NULL DEFAULT 0,
                `socketContent_2` int(11) NOT NULL DEFAULT 0,
                `socketColor_3` int(11) NOT NULL DEFAULT 0,
                `socketContent_3` int(11) NOT NULL DEFAULT 0,
                `socketBonus` int(11) NOT NULL DEFAULT 0,
                `GemProperties` int(11) NOT NULL DEFAULT 0,
                `ArmorDamageModifier` float NOT NULL DEFAULT 0,
                `Duration` int(11) NOT NULL DEFAULT 0 COMMENT 'Items may have a duration set until the get removed from a character''s inventory',
                `ItemLimitCategory` int(11) NOT NULL DEFAULT 0,
                `HolidayId` int(11) NOT NULL DEFAULT 0,
                `StatScalingFactor` float NOT NULL DEFAULT 0,
                `Unknown400_1` int(11) NOT NULL DEFAULT 0,
                `Unknown400_2` int(11) NOT NULL DEFAULT 0,
                PRIMARY KEY (`entry`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='The client fields of the items the client files do not hold';

            -- The entries Item-sparse.db2 of the 15595 client holds, as ranges.
            DROP TEMPORARY TABLE IF EXISTS `client_item_ranges`;
            CREATE TEMPORARY TABLE `client_item_ranges` (
                `first` mediumint(8) unsigned NOT NULL,
                `last` mediumint(8) unsigned NOT NULL,
                PRIMARY KEY (`last`)
            );

            -- The ranges are disjoint, so the one that ends first at or after an
            -- entry is the only one that can hold it.
                `entry`, `class`, `subclass`, `unk0`, `name`, `displayid`, `Quality`, `Flags`,
                `Flags2`, `Unknown`, `Unknown1`, `BuyCount`, `BuyPrice`, `SellPrice`,
                `InventoryType`, `AllowableClass`, `AllowableRace`, `ItemLevel`, `RequiredLevel`,
                `RequiredSkill`, `RequiredSkillRank`, `requiredspell`, `requiredhonorrank`,
                `RequiredCityRank`, `RequiredReputationFaction`, `RequiredReputationRank`,
                `maxcount`, `stackable`, `ContainerSlots`, `stat_type1`, `stat_value1`,
                `stat_unk1_1`, `stat_unk2_1`, `stat_type2`, `stat_value2`, `stat_unk1_2`,
                `stat_unk2_2`, `stat_type3`, `stat_value3`, `stat_unk1_3`, `stat_unk2_3`,
                `stat_type4`, `stat_value4`, `stat_unk1_4`, `stat_unk2_4`, `stat_type5`,
                `stat_value5`, `stat_unk1_5`, `stat_unk2_5`, `stat_type6`, `stat_value6`,
                `stat_unk1_6`, `stat_unk2_6`, `stat_type7`, `stat_value7`, `stat_unk1_7`,
                `stat_unk2_7`, `stat_type8`, `stat_value8`, `stat_unk1_8`, `stat_unk2_8`,
                `stat_type9`, `stat_value9`, `stat_unk1_9`, `stat_unk2_9`, `stat_type10`,
                `stat_value10`, `stat_unk1_10`, `stat_unk2_10`, `ScalingStatDistribution`,
                `DamageType`, `delay`, `RangedModRange`, `spellid_1`, `spelltrigger_1`,
                `spellcharges_1`, `spellcooldown_1`, `spellcategory_1`, `spellcategorycooldown_1`,
                `spellid_2`, `spelltrigger_2`, `spellcharges_2`, `spellcooldown_2`,
                `spellcategory_2`, `spellcategorycooldown_2`, `spellid_3`, `spelltrigger_3`,
                `spellcharges_3`, `spellcooldown_3`, `spellcategory_3`, `spellcategorycooldown_3`,
                `spellid_4`, `spelltrigger_4`, `spellcharges_4`, `spellcooldown_4`,
                `spellcategory_4`, `spellcategorycooldown_4`, `spellid_5`, `spelltrigger_5`,
                `spellcharges_5`, `spellcooldown_5`, `spellcategory_5`, `spellcategorycooldown_5`,
                `bonding`, `description`, `PageText`, `LanguageID`, `PageMaterial`, `startquest`,
                `lockid`, `Material`, `sheath`, `RandomProperty`, `RandomSuffix`, `itemset`,
                `area`, `Map`, `BagFamily`, `TotemCategory`, `socketColor_1`, `socketContent_1`,
                `socketColor_2`, `socketContent_2`, `socketColor_3`, `socketContent_3`,
                `socketBonus`, `GemProperties`, `ArmorDamageModifier`, `Duration`,
                `ItemLimitCategory`, `HolidayId`, `StatScalingFactor`, `Unknown400_1`,
                `Unknown400_2`)
            SELECT
                   `entry`, `class`, `subclass`, `unk0`, `name`, `displayid`, `Quality`, `Flags`,
                   `Flags2`, `Unknown`, `Unknown1`, `BuyCount`, `BuyPrice`, `SellPrice`,
                   `InventoryType`, `AllowableClass`, `AllowableRace`, `ItemLevel`,
                   `RequiredLevel`, `RequiredSkill`, `RequiredSkillRank`, `requiredspell`,
                   `requiredhonorrank`, `RequiredCityRank`, `RequiredReputationFaction`,
                   `RequiredReputationRank`, `maxcount`, `stackable`, `ContainerSlots`,
                   `stat_type1`, `stat_value1`, `stat_unk1_1`, `stat_unk2_1`, `stat_type2`,
                   `stat_value2`, `stat_unk1_2`, `stat_unk2_2`, `stat_type3`, `stat_value3`,
                   `stat_unk1_3`, `stat_unk2_3`, `stat_type4`, `stat_value4`, `stat_unk1_4`,
                   `stat_unk2_4`, `stat_type5`, `stat_value5`, `stat_unk1_5`, `stat_unk2_5`,
                   `stat_type6`, `stat_value6`, `stat_unk1_6`, `stat_unk2_6`, `stat_type7`,
                   `stat_value7`, `stat_unk1_7`, `stat_unk2_7`, `stat_type8`, `stat_value8`,
                   `stat_unk1_8`, `stat_unk2_8`, `stat_type9`, `stat_value9`, `stat_unk1_9`,
                   `stat_unk2_9`, `stat_type10`, `stat_value10`, `stat_unk1_10`, `stat_unk2_10`,
                   `ScalingStatDistribution`, `DamageType`, `delay`, `RangedModRange`, `spellid_1`,
                   `spelltrigger_1`, `spellcharges_1`, `spellcooldown_1`, `spellcategory_1`,
                   `spellcategorycooldown_1`, `spellid_2`, `spelltrigger_2`, `spellcharges_2`,
                   `spellcooldown_2`, `spellcategory_2`, `spellcategorycooldown_2`, `spellid_3`,
                   `spelltrigger_3`, `spellcharges_3`, `spellcooldown_3`, `spellcategory_3`,
                   `spellcategorycooldown_3`, `spellid_4`, `spelltrigger_4`, `spellcharges_4`,
                   `spellcooldown_4`, `spellcategory_4`, `spellcategorycooldown_4`, `spellid_5`,
                   `spelltrigger_5`, `spellcharges_5`, `spellcooldown_5`, `spellcategory_5`,
                   `spellcategorycooldown_5`, `bonding`, `description`, `PageText`, `LanguageID`,
                   `PageMaterial`, `startquest`, `lockid`, `Material`, `sheath`, `RandomProperty`,
                   `RandomSuffix`, `itemset`, `area`, `Map`, `BagFamily`, `TotemCategory`,
                   `socketColor_1`, `socketContent_1`, `socketColor_2`, `socketContent_2`,
                   `socketColor_3`, `socketContent_3`, `socketBonus`, `GemProperties`,
                   `ArmorDamageModifier`, `Duration`, `ItemLimitCategory`, `HolidayId`,
                   `StatScalingFactor`, `Unknown400_1`, `Unknown400_2`
              FROM `item_template` AS `t`
             WHERE COALESCE((SELECT `r`.`first` FROM `client_item_ranges` AS `r`
                              WHERE `r`.`last` >= `t`.`entry`
                              ORDER BY `r`.`last` LIMIT 1), 16777216) > `t`.`entry`
                OR `t`.`entry` IN (SELECT `entry` FROM `hotfix_data` WHERE `type` = 2442913102);

            DROP TEMPORARY TABLE `client_item_ranges`;

            ALTER TABLE `item_template`
                DROP COLUMN `class`, DROP COLUMN `subclass`, DROP COLUMN `unk0`,
                DROP COLUMN `name`, DROP COLUMN `displayid`, DROP COLUMN `Quality`,
                DROP COLUMN `Flags`, DROP COLUMN `Flags2`, DROP COLUMN `Unknown`,
                DROP COLUMN `Unknown1`, DROP COLUMN `BuyCount`, DROP COLUMN `BuyPrice`,
                DROP COLUMN `SellPrice`, DROP COLUMN `InventoryType`, DROP COLUMN `AllowableClass`,
                DROP COLUMN `AllowableRace`, DROP COLUMN `ItemLevel`, DROP COLUMN `RequiredLevel`,
                DROP COLUMN `RequiredSkill`, DROP COLUMN `RequiredSkillRank`,
                DROP COLUMN `requiredspell`, DROP COLUMN `requiredhonorrank`,
                DROP COLUMN `RequiredCityRank`, DROP COLUMN `RequiredReputationFaction`,
                DROP COLUMN `RequiredReputationRank`, DROP COLUMN `maxcount`,
                DROP COLUMN `stackable`, DROP COLUMN `ContainerSlots`, DROP COLUMN `stat_type1`,
