                DROP COLUMN `stat_type5`, DROP COLUMN `stat_value5`, DROP COLUMN `stat_unk1_5`,
                DROP COLUMN `stat_unk2_5`, DROP COLUMN `stat_type6`, DROP COLUMN `stat_value6`,
                DROP COLUMN `stat_unk1_6`, DROP COLUMN `stat_unk2_6`, DROP COLUMN `stat_type7`,
                DROP COLUMN `stat_value7`, DROP COLUMN `stat_unk1_7`, DROP COLUMN `stat_unk2_7`,
                DROP COLUMN `stat_type8`, DROP COLUMN `stat_value8`, DROP COLUMN `stat_unk1_8`,
                DROP COLUMN `stat_unk2_8`, DROP COLUMN `stat_type9`, DROP COLUMN `stat_value9`,
                DROP COLUMN `stat_unk1_9`, DROP COLUMN `stat_unk2_9`, DROP COLUMN `stat_type10`,
                DROP COLUMN `stat_value10`, DROP COLUMN `stat_unk1_10`, DROP COLUMN `stat_unk2_10`,
                DROP COLUMN `ScalingStatDistribution`, DROP COLUMN `DamageType`,
                DROP COLUMN `delay`, DROP COLUMN `RangedModRange`, DROP COLUMN `spellid_1`,
                DROP COLUMN `spelltrigger_1`, DROP COLUMN `spellcharges_1`,
                DROP COLUMN `spellcooldown_1`, DROP COLUMN `spellcategory_1`,
                DROP COLUMN `spellcategorycooldown_1`, DROP COLUMN `spellid_2`,
                DROP COLUMN `spelltrigger_2`, DROP COLUMN `spellcharges_2`,
                DROP COLUMN `spellcooldown_2`, DROP COLUMN `spellcategory_2`,
                DROP COLUMN `spellcategorycooldown_2`, DROP COLUMN `spellid_3`,
                DROP COLUMN `spelltrigger_3`, DROP COLUMN `spellcharges_3`,
                DROP COLUMN `spellcooldown_3`, DROP COLUMN `spellcategory_3`,
                DROP COLUMN `spellcategorycooldown_3`, DROP COLUMN `spellid_4`,
                DROP COLUMN `spelltrigger_4`, DROP COLUMN `spellcharges_4`,
                DROP COLUMN `spellcooldown_4`, DROP COLUMN `spellcategory_4`,
                DROP COLUMN `spellcategorycooldown_4`, DROP COLUMN `spellid_5`,
                DROP COLUMN `spelltrigger_5`, DROP COLUMN `spellcharges_5`,
                DROP COLUMN `spellcooldown_5`, DROP COLUMN `spellcategory_5`,
                DROP COLUMN `spellcategorycooldown_5`, DROP COLUMN `bonding`,
                DROP COLUMN `description`, DROP COLUMN `PageText`, DROP COLUMN `LanguageID`,
                DROP COLUMN `PageMaterial`, DROP COLUMN `startquest`, DROP COLUMN `lockid`,
                DROP COLUMN `Material`, DROP COLUMN `sheath`, DROP COLUMN `RandomProperty`,
                DROP COLUMN `RandomSuffix`, DROP COLUMN `itemset`, DROP COLUMN `area`,
                DROP COLUMN `Map`, DROP COLUMN `BagFamily`, DROP COLUMN `TotemCategory`,
                DROP COLUMN `socketColor_1`, DROP COLUMN `socketContent_1`,
                DROP COLUMN `socketColor_2`, DROP COLUMN `socketContent_2`,
                DROP COLUMN `socketColor_3`, DROP COLUMN `socketContent_3`,
                DROP COLUMN `socketBonus`, DROP COLUMN `GemProperties`,
                DROP COLUMN `ArmorDamageModifier`, DROP COLUMN `Duration`,
                DROP COLUMN `ItemLimitCategory`, DROP COLUMN `HolidayId`,
                DROP COLUMN `StatScalingFactor`, DROP COLUMN `Unknown400_1`,
                DROP COLUMN `Unknown400_2`, DROP COLUMN `Unknown2`;
        END IF;

        START TRANSACTION;
            @cNewContent, @cNewDescription, @cNewComment);
        SET @cNewResult := (SELECT `description` FROM `db_version`
            WHERE `version` = @cNewVersion AND `structure` = @cNewStructure
              AND `content` = @cNewContent);
        COMMIT;
        SELECT '* UPDATE COMPLETE *' AS `===== Status =====`,
               @cNewResult AS `===== DB is now on Version =====`;
    ELSE
        IF (@cCurResult = @cNewResult) THEN
            SELECT '* UPDATE SKIPPED *' AS `===== Status =====`,
                   @cCurResult AS `===== DB is already on Version =====`;
        ELSE
            IF (@cCurResult IS NULL) THEN
                SELECT '* UPDATE FAILED *' AS `===== Status =====`,
                       'Unable to locate DB Version Information' AS `============= Error Message =============`;
            ELSE
                SET @cCurOutput = CONCAT(@cCurVersion, '_', @cCurStructure,
                    '_', @cCurContent, ' - ', @cCurResult);
                SET @cOldOutput = CONCAT(@cOldVersion, '_', @cOldStructure,
                    '_', @cOldContent, ' - ',
                    COALESCE(@cOldResult, 'IS NOT APPLIED'));
                SELECT '* UPDATE SKIPPED *' AS `===== Status =====`,
                       @cOldOutput AS `=== Expected ===`,
                       @cCurOutput AS `===== Found Version =====`;
            END IF;
        END IF;
    END IF;
END$$

DELIMITER ;

CALL `update_mangos`();
DROP PROCEDURE IF EXISTS `update_mangos`;
